insert into public.library_creatives (slug, brand, title, industry, platform, format, angles, summary, hook, visual_strategy, offer, messaging, cta, why_study, test_idea, preview_kind, youtube_id, image_url, image_width, image_height, headline, source_url, source_label, attribution, year, label, evidence_url, evidence_note, sort_order)
values
  ('dollar-shave-club-our-blades', 'Dollar Shave Club', 'Our Blades Are F***ing Great', 'E-commerce', 'YouTube', 'video', array['founder-led', 'offer-led', 'humor']::text[], 'The founder walks through the warehouse and sells the whole business model — price, convenience, quality — in one continuous, deadpan take.', 'Opens with the founder saying who he is and that blades cost $1 a month — the offer lands in the first seconds.', 'One fast tracking shot through a real warehouse; low-budget props make each joke a visual beat.', 'Quality razor blades delivered for $1 a month.', 'You''re overpaying for blades you have to go to a store to buy. This is cheaper and simpler.', 'Visit DollarShaveClub.com.', 'Shows how a founder on camera can carry price, product and personality without a polished production.', 'Record your founder or owner stating the offer in the first line, then cut every sentence that isn''t a reason to buy.', 'youtube', 'ZUG9qYTJMsI', null, null, null, null, 'https://www.youtube.com/watch?v=ZUG9qYTJMsI', 'YouTube · Dollar Shave Club', 'Dollar Shave Club (2012)', 2012, 'verified_winner', 'https://www.entrepreneur.com/growing-a-business/how-a-dollar-shave-clubs-ad-went-viral/224282', 'Entrepreneur (Oct 2012): "In the first 48 hours after the video debuted on YouTube, some 12,000 people signed up for the service."', 10),
  ('squatty-potty-unicorn', 'Squatty Potty', 'This Unicorn Changed the Way I Poop', 'E-commerce', 'YouTube', 'video', array['problem-solution', 'product-demo', 'humor']::text[], 'An absurd fairy-tale frame (a prince and a unicorn) makes an awkward product easy to talk about, then explains the mechanism clearly.', 'A prince in a storybook kingdom promises to explain "the science of pooping" — a pattern interrupt nobody scrolls past.', 'Bright fantasy set, a diagram-style explanation of posture, and a clear shot of the product in use.', 'A toilet stool that changes your posture.', 'The way you sit is the problem; a simple stool is the fix.', 'Buy the Squatty Potty online.', 'A textbook problem → mechanism → solution script wrapped in humour, for a product people don''t want to discuss.', 'Explain *why* your product works with one simple visual (a diagram or side-by-side) before you show the price.', 'youtube', 'YbYWhdLO43Q', null, null, null, null, 'https://www.youtube.com/watch?v=YbYWhdLO43Q', 'YouTube · Squatty Potty', 'Squatty Potty, produced with Harmon Brothers (2015)', 2015, 'verified_winner', 'https://www.entrepreneur.com/leadership/this-company-found-a-way-to-sell-something-no-one-wants-to/273490', 'Entrepreneur (Apr 2016): "The return: 30 million views in a week, and revenues 600 percent higher than projected."', 20),
  ('blendtec-will-it-blend-iphone', 'Blendtec', 'Will It Blend? — iPhone', 'Home & Living', 'YouTube', 'video', array['product-demo']::text[], 'The CEO blends a brand-new iPhone. A recurring, repeatable demo format that proves power without a single claim.', 'The question "Will it blend?" plus an object nobody would put in a blender.', 'Plain lab-coat setup, close-up of the jar, and the result (dust) shown as proof.', 'None stated in the video — the product''s power is the message.', 'This blender is strong enough to destroy anything.', 'Implicit: remember the brand; the series points viewers to Blendtec.', 'Demonstration beats description: one extreme, visual test does the job of a spec sheet.', 'Find the most extreme, visual test your product can pass and make the result the thumbnail.', 'youtube', 'qg1ckCkm8YI', null, null, null, null, 'https://www.youtube.com/watch?v=qg1ckCkm8YI', 'YouTube · Blendtec', 'Blendtec (2007)', 2007, 'verified_winner', 'https://magazine.byu.edu/article/will-it-blend', 'BYU Magazine (Spring 2009): "Within two years, the campaign helped increase retail blender sales 700 percent."', 30),
  ('dominos-pizza-turnaround', 'Domino''s', 'Pizza Turnaround', 'Food & Beverage', 'YouTube', 'video', array['before-after', 'problem-solution', 'storytelling']::text[], 'Domino''s reads real customer criticism on camera, admits the pizza was bad, and shows the team rebuilding it.', 'Customers calling the old pizza "cardboard" — said out loud, by the brand itself.', 'Documentary style: focus-group footage, kitchen tests and leadership speaking directly to camera.', 'A new pizza recipe — try it again.', 'We heard you, we changed the product, judge us again.', 'Try the new pizza.', 'Shows how admitting a weakness can create trust and a reason to re-try — the "before" makes the "after" believable.', 'Quote a real piece of customer criticism in your ad and show what you changed because of it.', 'youtube', 'AH5R56jILag', null, null, null, null, 'https://www.youtube.com/watch?v=AH5R56jILag', 'YouTube · Domino''s Pizza', 'Domino''s, with Crispin Porter + Bogusky (2009–2010)', 2009, 'verified_winner', 'https://www.convenience.org/Archive/News/NACSDailyArticles/2011/ND0510117', 'NACS Daily (May 2011, "Self-Deprecation Pays Dividends for Domino''s"): first-quarter sales for Domino''s U.S. stores were up 14.3% year-on-year in Q1 2010.', 40),
  ('old-spice-man-your-man', 'Old Spice', 'The Man Your Man Could Smell Like', 'Beauty & Personal Care', 'YouTube', 'video', array['humor', 'celebrity']::text[], 'One unbroken, fast-talking take where the set changes around the presenter — speaking straight to the person who buys the product.', '"Hello, ladies" — addresses the actual buyer (partners buying body wash), not the user.', 'A single continuous shot with practical set changes; every few seconds a new surprise keeps attention.', 'Old Spice body wash.', 'Your man can''t be him, but he can smell like him.', 'Buy Old Spice body wash.', 'Speaks to the buyer rather than the user, and keeps attention with constant visual surprises in one shot.', 'If someone else often buys for your customer, write a version that talks directly to that buyer.', 'youtube', 'owGykVbfgUE', null, null, null, null, 'https://www.youtube.com/watch?v=owGykVbfgUE', 'YouTube · Old Spice', 'Old Spice, with Wieden+Kennedy (2010)', 2010, 'inspiration', null, null, 50),
  ('poo-pourri-girls-dont-poop', 'Poo~Pourri', 'Girls Don''t Poop', 'Beauty & Personal Care', 'YouTube', 'video', array['problem-solution', 'humor', 'product-demo']::text[], 'A prim, confident spokesperson says the unsayable in polished language — turning an embarrassing problem into a shareable joke.', 'The title itself: a taboo statement delivered with total poise.', 'A polished bathroom set, a poised spokesperson and a simple how-to-use demonstration.', 'A before-you-go toilet spray.', 'Embarrassing bathroom smells, solved before they start.', 'Get Poo~Pourri online.', 'Contrast (classy delivery, crude topic) creates the hook; the demo keeps it a product ad, not just a sketch.', 'Say your customer''s most embarrassing problem plainly in the first line, in a tone that contrasts with it.', 'youtube', 'ZKLnhuzh9uY', null, null, null, null, 'https://www.youtube.com/watch?v=ZKLnhuzh9uY', 'YouTube · Poo~Pourri', 'Poo~Pourri (2013)', 2013, 'inspiration', null, null, 60),
  ('purple-raw-egg-test', 'Purple', 'How to Use a Raw Egg to Determine if Your Mattress Is Awful', 'Home & Living', 'YouTube', 'video', array['product-demo', 'comparison', 'humor']::text[], '"Goldilocks" drops raw eggs on other mattresses (they break) and on Purple (they don''t) — a comparison anyone understands instantly.', 'A raw-egg test — a visible, physical experiment instead of a comfort claim.', 'Clean studio and side-by-side tests, with the egg as the recurring visual proof.', 'The Purple mattress, sold online.', 'Pressure points are the problem; Purple''s grid relieves them — proven by the egg.', 'Shop Purple online.', 'Turns an invisible benefit (pressure relief) into a test you can see — the strongest kind of proof in a feed.', 'Design a simple physical test that shows your benefit on screen and compare against "the usual way".', 'youtube', '4BvwpjaGZCQ', null, null, null, null, 'https://www.youtube.com/watch?v=4BvwpjaGZCQ', 'YouTube · Purple', 'Purple, produced with Harmon Brothers (2016)', 2016, 'strong_structure', null, null, 70),
  ('ikea-bookbook', 'IKEA', 'Experience the Power of a Bookbook™', 'Home & Living', 'YouTube', 'video', array['humor', 'product-demo']::text[], 'IKEA presents its printed catalogue like a tech-product launch, praising its "battery life" and "loading speed" — borrowing a format everyone recognizes.', 'Familiar tech-keynote styling applied to a paper catalogue.', 'Minimal white studio, slow product close-ups and a presenter in the style of a product keynote.', 'The free IKEA catalogue.', 'The simplest thing can be presented as innovative.', 'Get your IKEA catalogue.', 'Parodying a well-known ad format gives instant context and makes an everyday product feel new.', 'Present your most ordinary product in the visual language of a premium launch.', 'youtube', 'MOXQo7nURs0', null, null, null, null, 'https://www.youtube.com/watch?v=MOXQo7nURs0', 'YouTube · IKEA Singapore', 'IKEA Singapore (2014)', 2014, 'inspiration', null, null, 80),
  ('volvo-trucks-epic-split', 'Volvo Trucks', 'The Epic Split feat. Van Damme', 'Automotive', 'YouTube', 'video', array['product-demo', 'celebrity']::text[], 'Jean-Claude Van Damme does the splits between two reversing trucks — a dramatic stunt that proves the steering is precise.', 'A calm close-up and voiceover; the camera pulls back to reveal the impossible position.', 'One slow reveal at sunrise; nothing on screen distracts from the stunt.', 'Volvo Dynamic Steering.', 'The steering is so precise and stable you could do this.', 'Learn more about Volvo Dynamic Steering.', 'Shows a technical feature through one unforgettable image instead of a list of specs.', 'Turn your most technical feature into one visual stunt or test, and reveal it slowly.', 'youtube', 'M7FIvfx5J10', null, null, null, null, 'https://www.youtube.com/watch?v=M7FIvfx5J10', 'YouTube · Volvo Trucks', 'Volvo Trucks, with Forsman & Bodenfors (2013)', 2013, 'inspiration', null, null, 90),
  ('google-parisian-love', 'Google', 'Parisian Love', 'SaaS & Tech', 'YouTube', 'video', array['storytelling', 'product-demo']::text[], 'A whole love story told only through search queries typed into Google — the product interface is the story.', 'A real search box and a curious query: "study abroad paris france".', 'Screen recording only: typing, results, and the next query. No actors on screen.', 'Google Search.', 'Search helps with every step of your life.', 'Search on.', 'Proof that a product''s own interface can carry emotion — ideal for software and apps.', 'Script a short ad that is only your product''s screen, showing a customer''s journey step by step.', 'youtube', 'nnsSUqgkDwU', null, null, null, null, 'https://www.youtube.com/watch?v=nnsSUqgkDwU', 'YouTube · Google', 'Google (2009)', 2009, 'strong_structure', null, null, 100),
  ('slack-so-yeah-we-tried-slack', 'Slack', 'So Yeah, We Tried Slack…', 'SaaS & Tech', 'YouTube', 'video', array['product-demo', 'humor', 'problem-solution']::text[], 'A small team explains, in deadpan interview style, how their messy communication changed after switching to Slack.', 'A relatable confession about workplace communication chaos.', 'Mockumentary interviews intercut with clean product UI.', 'Slack for team communication.', 'Fewer emails and lost messages; everything in one searchable place.', 'Try Slack.', 'A product walkthrough that feels like a story because it''s told by "customers" with personality.', 'Show your product UI inside a short customer-style story instead of a voiced-over feature tour.', 'youtube', 'B6zVzWU95Sw', null, null, null, null, 'https://www.youtube.com/watch?v=B6zVzWU95Sw', 'YouTube · Slack', 'Slack, produced by Sandwich Video (2015)', 2015, 'strong_structure', null, null, 110),
  ('gopro-fireman-saves-kitten', 'GoPro', 'Fireman Saves Kitten', 'SaaS & Tech', 'YouTube', 'video', array['ugc', 'storytelling']::text[], 'Real helmet-camera footage from a firefighter rescuing a kitten. The customer''s footage is the ad.', 'Point-of-view footage of a real emergency.', 'Unpolished first-person footage, minimal titles, and the camera''s own perspective.', 'GoPro cameras.', 'Real moments, captured by the people living them.', 'Implicit: the GoPro brand and channel.', 'The strongest UGC is a real moment the product made possible — not a script read by a creator.', 'Ask customers for footage of a real moment your product was part of, and lead with that moment.', 'youtube', 'CjB_oVeq8Lo', null, null, null, null, 'https://www.youtube.com/watch?v=CjB_oVeq8Lo', 'YouTube · GoPro', 'GoPro, footage from a firefighter''s helmet camera (2013)', 2013, 'inspiration', null, null, 120),
  ('cerave-michael-cerave', 'CeraVe', 'Michael CeraVe', 'Beauty & Personal Care', 'YouTube', 'video', array['celebrity', 'humor']::text[], 'Michael Cera claims he invented CeraVe — then the brand corrects him: "Developed with dermatologists. Not Michael Cera."', 'A recognizable actor whose name is literally inside the brand name.', 'Glossy, slightly absurd beauty-ad visuals, ending on a boardroom of unimpressed dermatologists.', 'CeraVe Moisturizing Cream.', 'Developed with dermatologists (the real credibility point), delivered as the punchline.', 'Implicit: the product and the dermatologist claim.', 'The joke ends on the brand''s core proof point, so the humour reinforces the message instead of hiding it.', 'Write a humorous ad whose punchline is your strongest proof point.', 'youtube', 'vAf5TjiUJgo', null, null, null, null, 'https://www.youtube.com/watch?v=vAf5TjiUJgo', 'YouTube · CeraVe', 'CeraVe, Super Bowl LVIII (2024)', 2024, 'inspiration', null, null, 130),
  ('dove-reverse-selfie', 'Dove', 'Reverse Selfie', 'Beauty & Personal Care', 'YouTube', 'video', array['before-after', 'brand-stance', 'storytelling']::text[], 'A heavily edited selfie is undone step by step until the real subject is revealed: a young girl.', 'A familiar "perfect" social post that starts playing in reverse.', 'Phone-screen editing UI shown backwards — each removed filter is a visual beat.', 'The Dove Self-Esteem Project''s Confidence Kit (free resources).', 'Digital distortion harms girls'' self-esteem.', 'Have the selfie talk with a girl you love.', 'A before/after told in reverse: the reveal is the message.', 'Try a reverse before/after: start with the end result and rewind to the starting point.', 'youtube', 'z2T-Rh838GA', null, null, null, null, 'https://www.youtube.com/watch?v=z2T-Rh838GA', 'YouTube · Dove US', 'Dove, with Ogilvy (2021)', 2021, 'inspiration', null, null, 140),
  ('liquid-death-iced-tea-grandma', 'Liquid Death', 'Your Grandma''s Energy Drink', 'Food & Beverage', 'YouTube', 'video', array['humor']::text[], 'Grandmothers singing death metal to sell iced tea — the brand''s irreverent tone in its purest form.', 'The visual contrast of grandmothers and death-metal vocals.', 'Heavy-metal music-video styling applied to an unexpected cast.', 'Liquid Death Iced Tea.', 'Like your grandma''s iced tea — just a lot more metal.', 'Implicit: try the new iced tea.', 'Shows how a strong, consistent brand tone can make a commodity product (water, tea) memorable.', 'Cast someone your audience wouldn''t expect for your category, keeping your brand voice.', 'youtube', 'cXdZpsf5BI8', null, null, null, null, 'https://www.youtube.com/watch?v=cXdZpsf5BI8', 'YouTube · Liquid Death', 'Liquid Death (2023)', 2023, 'inspiration', null, null, 150),
  ('peloton-its-you-that-makes-us', 'Peloton', 'It''s You. That Makes Us.', 'Fitness & Wellness', 'YouTube', 'video', array['celebrity', 'social-proof', 'storytelling']::text[], 'Pro athletes and members working out at home, framed as one global community.', 'Recognisable athletes training alongside everyday members.', 'Fast cuts between elite athletes and members at home, tied together by one line.', 'The Peloton platform and community.', 'You''re never training alone — the community makes the motivation.', 'Join the community.', 'Uses aspirational athletes and relatable members together, so the viewer sees both the goal and themselves.', 'Pair one aspirational figure with real customers in the same ad, using one line to connect them.', 'youtube', '1WPWGKxWyk4', null, null, null, null, 'https://www.youtube.com/watch?v=1WPWGKxWyk4', 'YouTube · Peloton', 'Peloton (2021)', 2021, 'inspiration', null, null, 160),
  ('warby-parker-eyeballs', 'Warby Parker', 'Eyeballs Looking for Glasses', 'Fashion & Lifestyle', 'YouTube', 'video', array['storytelling']::text[], 'Warby Parker''s first TV spot, mixing film, animation and collage to introduce the brand.', 'Playful, handmade-looking animation — distinctive in a category of glossy eyewear ads.', 'Film, animation and collage combined; the art direction carries the brand personality.', 'Warby Parker glasses, bought online.', 'A playful, design-led way to buy glasses.', 'Visit warbyparker.com.', 'A distinctive art style can make a direct-to-consumer brand recognizable from the first frame.', 'Test an ad with a handmade or collage visual style against your usual product photography.', 'youtube', 'lV-afyZ46aQ', null, null, null, null, 'https://www.youtube.com/watch?v=lV-afyZ46aQ', 'YouTube · Warby Parker', 'Warby Parker, created by Partners & Spade (2012)', 2012, 'inspiration', null, null, 170),
  ('patagonia-dont-buy-this-jacket', 'Patagonia', 'Don''t Buy This Jacket', 'Fashion & Lifestyle', 'Print', 'image', array['brand-stance']::text[], 'A full-page Black Friday ad telling readers not to buy the jacket in the photo — and to think before consuming.', 'A headline that contradicts what every ad is supposed to say.', 'One product photo under a bold, counter-intuitive headline; dense explanatory copy below.', 'The Common Threads Initiative pledge: reduce, repair, reuse, recycle.', 'Buy less, buy better — even from us.', 'Take the Common Threads pledge.', 'A pattern-breaking headline backed by a genuine brand belief earns attention on the busiest shopping day.', 'Write a headline that says the opposite of what your category usually says — then justify it.', 'none', null, null, null, null, 'Don''t buy this jacket', 'https://www.patagonia.com/stories/dont-buy-this-jacket-black-friday-and-the-new-york-times/story-18615.html', 'Patagonia Stories', 'Patagonia, The New York Times, Black Friday 2011', 2011, 'inspiration', null, null, 180),
  ('volkswagen-think-small', 'Volkswagen', 'Think Small', 'Automotive', 'Print', 'image', array['brand-stance', 'problem-solution']::text[], 'A tiny Beetle in a sea of white space, with honest copy about the car''s small size as a benefit.', 'Mostly empty space — the small car looks even smaller, which is the point.', 'Black and white, a small product image top-left, a short headline with a full stop, three columns of copy.', 'The Volkswagen Beetle.', 'Small is a benefit: cheaper to run, easier to park.', 'Implicit: consider the Beetle.', 'Turns the product''s apparent weakness into its main selling point with radically simple layout.', 'Make the thing customers see as a weakness your headline, and explain why it''s an advantage.', 'none', null, null, null, null, 'Think small.', 'https://en.wikipedia.org/wiki/Think_Small', 'Wikipedia', 'Volkswagen of America, with Doyle Dane Bernbach (1959)', 1959, 'strong_structure', null, null, 190),
  ('kfc-fck-apology', 'KFC', 'FCK — We''re Sorry', 'Food & Beverage', 'Print', 'image', array['brand-stance', 'humor']::text[], 'During a UK chicken shortage, KFC ran a full-page apology showing its bucket with the letters rearranged to "FCK".', 'Three rearranged letters on an instantly recognizable bucket.', 'A single product image on a red background with a short, direct apology underneath.', 'None — an apology.', 'We messed up, we''re sorry, and we''re fixing it.', 'Implicit: forgive us and come back.', 'Shows how a brand can own a mistake with self-aware humour instead of a corporate statement.', 'When something goes wrong, test a short, human, slightly self-deprecating message.', 'none', null, null, null, null, 'FCK', 'https://www.campaignlive.co.uk/article/kfcs-were-sorry-mother-wins-cannes-lions-gold-print-publishing/1485469', 'Campaign', 'KFC UK & Ireland, with Mother London (2018)', 2018, 'inspiration', null, null, 200)
